class Solution {
public:
    int robotSim(vector<int>& commands, vector<vector<int>>& obstacles) {
        unordered_set<long long> obs;
        obs.reserve(obstacles.size() * 2);
        for (auto& o : obstacles) {
            long long key = ((long long)(o[0] + 100000)) * 300000LL + (o[1] + 100000);
            obs.insert(key);
        }
        int dx[4] = {0, 1, 0, -1};
        int dy[4] = {1, 0, -1, 0};
        int x = 0, y = 0, dir = 0;
        long long ans = 0;
        for (int c : commands) {
            if (c == -2) {
                dir = (dir + 3) % 4;
            } else if (c == -1) {
                dir = (dir + 1) % 4;
            } else {
                for (int i = 0; i < c; i++) {
                    int nx = x + dx[dir];
                    int ny = y + dy[dir];
                    long long key = ((long long)(nx + 100000)) * 300000LL + (ny + 100000);
                    if (obs.count(key)) break;
                    x = nx;
                    y = ny;
                    long long d = (long long)x * x + (long long)y * y;
                    if (d > ans) ans = d;
                }
            }
        }
        return (int)ans;
    }
};
